SELECT a.*, c.name AS category_name FROM knowledge_article a LEFT JOIN knowledge_category c ON a.category_id = c.id AND c.is_deleted = 0 WHERE a.is_deleted = 0 AND a.status = 'PUBLISHED'
AND (a.title LIKE CONCAT('%', #{keyword}, '%') OR a.content LIKE CONCAT('%', #{keyword}, '%'))
AND c.code = #{category}
ORDER BY a.sort ASC, a.create_time DESC LIMIT #{offset}, #{size}

SELECT COUNT(*) FROM knowledge_article a LEFT JOIN knowledge_category c ON a.category_id = c.id AND c.is_deleted = 0 WHERE a.is_deleted = 0
AND a.status = #{status}
AND a.status = 'PUBLISHED'
AND (a.title LIKE CONCAT('%', #{keyword}, '%') OR a.content LIKE CONCAT('%', #{keyword}, '%'))
AND c.code = #{category}

SELECT a.*, c.name AS category_name FROM knowledge_article a LEFT JOIN knowledge_category c ON a.category_id = c.id AND c.is_deleted = 0 WHERE a.is_deleted = 0
AND a.title LIKE CONCAT('%', #{keyword}, '%')
AND a.status = #{status}
ORDER BY a.sort ASC, a.create_time DESC LIMIT #{offset}, #{size}

